150	function turnPointsIntoStep(
151	    points: ArrayLike<number>,
152	    coordSys: Cartesian2D | Polar,
153	    stepTurnAt: 'start' | 'end' | 'middle',
154	    connectNulls: boolean
155	): number[] {
156	    const baseAxis = coordSys.getBaseAxis();
157	    const baseIndex = baseAxis.dim === 'x' || baseAxis.dim === 'radius' ? 0 : 1;
158	
159	    const stepPoints: number[] = [];
160	    let i = 0;
161	    const stepPt: number[] = [];
162	    const pt: number[] = [];
163	    const nextPt: number[] = [];
164	    const filteredPoints = [];
165	    if (connectNulls) {
166	      for (i = 0; i < points.length; i += 2) {
167	          if (!isNaN(points[i]) && !isNaN(points[i + 1])) {
168	              filteredPoints.push(points[i], points[i + 1]);
169	          }
170	      }
171	      points = filteredPoints;
172	    }
173	    for (i = 0; i < points.length - 2; i += 2) {
174	        nextPt[0] = points[i + 2];
175	        nextPt[1] = points[i + 3];
176	        pt[0] = points[i];
177	        pt[1] = points[i + 1];
178	        stepPoints.push(pt[0], pt[1]);
179	
180	        switch (stepTurnAt) {
181	            case 'end':
182	                stepPt[baseIndex] = nextPt[baseIndex];
183	                stepPt[1 - baseIndex] = pt[1 - baseIndex];
184	                stepPoints.push(stepPt[0], stepPt[1]);
185	                break;
186	            case 'middle':
187	                const middle = (pt[baseIndex] + nextPt[baseIndex]) / 2;
188	                const stepPt2 = [];
189	                stepPt[baseIndex] = stepPt2[baseIndex] = middle;
190	                stepPt[1 - baseIndex] = pt[1 - baseIndex];
191	                stepPt2[1 - baseIndex] = nextPt[1 - baseIndex];
192	                stepPoints.push(stepPt[0], stepPt[1]);
193	                stepPoints.push(stepPt2[0], stepPt2[1]);
194	                break;
195	            default:
196	                // default is start
197	                stepPt[baseIndex] = pt[baseIndex];
198	                stepPt[1 - baseIndex] = nextPt[1 - baseIndex];
199	                stepPoints.push(stepPt[0], stepPt[1]);
200	        }
201	    }
202	    // Last points
203	    stepPoints.push(points[i++], points[i++]);
204	    return stepPoints;
205	}
