33	/**
34	 * Draw smoothed line in non-monotone, in may cause undesired curve in extreme
35	 * situations. This should be used when points are non-monotone neither in x or
36	 * y dimension.
37	 */
38	function drawSegment(
39	    ctx: PathProxy,
40	    points: ArrayLike<number>,
41	    start: number,
42	    segLen: number,
43	    allLen: number,
44	    dir: number,
45	    smooth: number,
46	    smoothMonotone: 'x' | 'y' | 'none',
47	    connectNulls: boolean
48	) {
49	    let prevX: number;
50	    let prevY: number;
51	    let cpx0: number;
52	    let cpy0: number;
53	    let cpx1: number;
54	    let cpy1: number;
55	    let idx = start;
56	    let k = 0;
57	    for (; k < segLen; k++) {
58	
59	        let x = points[idx * 2];
60	        let y = points[idx * 2 + 1];
61	
62	        if (idx >= allLen || idx < 0) {
63	            break;
64	        }
65	        if (isPointNull(x, y)) {
66	            if (connectNulls) {
67	                idx += dir;
68	                continue;
69	            }
70	            break;
71	        }
72	
73	        if (idx === start) {
74	            ctx[dir > 0 ? 'moveTo' : 'lineTo'](x, y);
75	            cpx0 = x;
76	            cpy0 = y;
77	        }
78	        else {
79	            let dx = x - prevX;
80	            let dy = y - prevY;
81	
82	            // Ignore tiny segment.
83	            if ((dx * dx + dy * dy) < 0.5) {
84	                idx += dir;
85	                continue;
86	            }
87	
88	            if (smooth > 0) {
89	                let nextIdx = idx + dir;
90	                let nextX = points[nextIdx * 2];
91	                let nextY = points[nextIdx * 2 + 1];
92	                // Ignore duplicate point
93	                while (nextX === x && nextY === y && k < segLen) {
94	                    k++;
95	                    nextIdx += dir;
96	                    idx += dir;
97	                    nextX = points[nextIdx * 2];
98	                    nextY = points[nextIdx * 2 + 1];
99	                    x = points[idx * 2];
100	                    y = points[idx * 2 + 1];
101	                    dx = x - prevX;
102	                    dy = y - prevY;
103	                }
104	
105	                let tmpK = k + 1;
106	                if (connectNulls) {
107	                    // Find next point not null
108	                    while (isPointNull(nextX, nextY) && tmpK < segLen) {
109	                        tmpK++;
110	                        nextIdx += dir;
111	                        nextX = points[nextIdx * 2];
112	                        nextY = points[nextIdx * 2 + 1];
113	                    }
114	                }
115	
116	                let ratioNextSeg = 0.5;
117	                let vx: number = 0;
118	                let vy: number = 0;
119	                let nextCpx0;
120	                let nextCpy0;
121	                // Is last point
122	                if (tmpK >= segLen || isPointNull(nextX, nextY)) {
123	                    cpx1 = x;
124	                    cpy1 = y;
125	                }
126	                else {
127	                    vx = nextX - prevX;
128	                    vy = nextY - prevY;
129	
130	                    const dx0 = x - prevX;
131	                    const dx1 = nextX - x;
132	                    const dy0 = y - prevY;
133	                    const dy1 = nextY - y;
134	                    let lenPrevSeg;
135	                    let lenNextSeg;
136	                    if (smoothMonotone === 'x') {
137	                        lenPrevSeg = Math.abs(dx0);
138	                        lenNextSeg = Math.abs(dx1);
139	                        const dir = vx > 0 ? 1 : -1;
140	                        cpx1 = x - dir * lenPrevSeg * smooth;
141	                        cpy1 = y;
142	                        nextCpx0 = x + dir * lenNextSeg * smooth;
143	                        nextCpy0 = y;
144	                    }
145	                    else if (smoothMonotone === 'y') {
146	                        lenPrevSeg = Math.abs(dy0);
147	                        lenNextSeg = Math.abs(dy1);
148	                        const dir = vy > 0 ? 1 : -1;
149	                        cpx1 = x;
150	                        cpy1 = y - dir * lenPrevSeg * smooth;
151	                        nextCpx0 = x;
152	                        nextCpy0 = y + dir * lenNextSeg * smooth;
153	                    }
154	                    else {
155	                        lenPrevSeg = Math.sqrt(dx0 * dx0 + dy0 * dy0);
156	                        lenNextSeg = Math.sqrt(dx1 * dx1 + dy1 * dy1);
157	
158	                        // Use ratio of seg length
159	                        ratioNextSeg = lenNextSeg / (lenNextSeg + lenPrevSeg);
160	
161	                        cpx1 = x - vx * smooth * (1 - ratioNextSeg);
162	                        cpy1 = y - vy * smooth * (1 - ratioNextSeg);
163	
164	                        // cp0 of next segment
165	                        nextCpx0 = x + vx * smooth * ratioNextSeg;
166	                        nextCpy0 = y + vy * smooth * ratioNextSeg;
167	
168	                        // Smooth constraint between point and next point.
169	                        // Avoid exceeding extreme after smoothing.
170	                        nextCpx0 = mathMin(nextCpx0, mathMax(nextX, x));
171	                        nextCpy0 = mathMin(nextCpy0, mathMax(nextY, y));
172	                        nextCpx0 = mathMax(nextCpx0, mathMin(nextX, x));
173	                        nextCpy0 = mathMax(nextCpy0, mathMin(nextY, y));
174	                        // Reclaculate cp1 based on the adjusted cp0 of next seg.
175	                        vx = nextCpx0 - x;
176	                        vy = nextCpy0 - y;
177	
178	                        cpx1 = x - vx * lenPrevSeg / lenNextSeg;
179	                        cpy1 = y - vy * lenPrevSeg / lenNextSeg;
180	
181	                        // Smooth constraint between point and prev point.
182	                        // Avoid exceeding extreme after smoothing.
183	                        cpx1 = mathMin(cpx1, mathMax(prevX, x));
184	                        cpy1 = mathMin(cpy1, mathMax(prevY, y));
185	                        cpx1 = mathMax(cpx1, mathMin(prevX, x));
186	                        cpy1 = mathMax(cpy1, mathMin(prevY, y));
187	
188	                        // Adjust next cp0 again.
189	                        vx = x - cpx1;
190	                        vy = y - cpy1;
191	                        nextCpx0 = x + vx * lenNextSeg / lenPrevSeg;
192	                        nextCpy0 = y + vy * lenNextSeg / lenPrevSeg;
193	                    }
194	                }
195	
196	                ctx.bezierCurveTo(cpx0, cpy0, cpx1, cpy1, x, y);
197	
198	                cpx0 = nextCpx0;
199	                cpy0 = nextCpy0;
200	            }
201	            else {
202	                ctx.lineTo(x, y);
203	            }
204	        }
205	
206	        prevX = x;
207	        prevY = y;
208	        idx += dir;
209	    }
210	
211	    return k;
212	}
