281	            this.buildPath(this.path, this.shape);
282	        }
283	        const path = this.path;
284	        const data = path.data;
285	        const CMD = PathProxy.CMD;
286	
287	        let x0;
288	        let y0;
289	
290	        const isDimX = dim === 'x';
291	        const roots: number[] = [];
292	
293	        for (let i = 0; i < data.length;) {
294	            const cmd = data[i++];
295	            let x;
296	            let y;
297	            let x2;
298	            let y2;
299	            let x3;
300	            let y3;
301	            let t;
302	            switch (cmd) {
303	                case CMD.M:
304	                    x0 = data[i++];
305	                    y0 = data[i++];
306	                    break;
307	                case CMD.L:
308	                    x = data[i++];
