314	                            : (x - x0) * t + x0;
315	                        return isDimX ? [xOrY, val] : [val, xOrY];
316	                    }
317	                    x0 = x;
318	                    y0 = y;
319	                    break;
320	                case CMD.C:
321	                    x = data[i++];
322	                    y = data[i++];
323	                    x2 = data[i++];
324	                    y2 = data[i++];
325	                    x3 = data[i++];
326	                    y3 = data[i++];
327	
328	                    const nRoot = isDimX ? cubicRootAt(x0, x, x2, x3, xOrY, roots)
329	                        : cubicRootAt(y0, y, y2, y3, xOrY, roots);
330	                    if (nRoot > 0) {
331	                        for (let i = 0; i < nRoot; i++) {
332	                            const t = roots[i];
333	                            if (t <= 1 && t >= 0) {
334	                                const val = isDimX ? cubicAt(y0, y, y2, y3, t)
335	                                    : cubicAt(x0, x, x2, x3, t);
336	                                return isDimX ? [xOrY, val] : [val, xOrY];
337	                            }
338	                        }
339	                    }
340	
341	                    x0 = x3;
342	                    y0 = y3;
