import { EChartsType } from '@/src/echarts';
import { createChart, getGraphicElements, removeChart } from '../../../core/utHelper';
import { LineSeriesOption } from '@/src/chart/line/LineSeries';

type PolyEl = {
    type: string
    shape: {
        points: ArrayLike<number>
        stackedOnPoints?: ArrayLike<number>
    }
};

function getPolyEl(chart: EChartsType, type: 'ec-polyline' | 'ec-polygon', seriesIndex?: number): PolyEl {
    const els = getGraphicElements(chart, 'series', seriesIndex || 0);
    for (let i = 0; i < els.length; i++) {
        if (els[i].type === type) {
            return els[i] as unknown as PolyEl;
        }
    }
    return null;
}

// Base axis is `x` here, so the base coord of a point is at the even offsets.
function getBaseCoords(points: ArrayLike<number>): number[] {
    const result: number[] = [];
    for (let i = 0; i < points.length; i += 2) {
        result.push(points[i]);
    }
    return result;
}

function getValueCoords(points: ArrayLike<number>): number[] {
    const result: number[] = [];
    for (let i = 1; i < points.length; i += 2) {
        result.push(points[i]);
    }
    return result;
}

describe('chart/line/step', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        removeChart(chart);
    });

    function setStepOption(series: LineSeriesOption) {
        chart.setOption({
            animation: false,
            xAxis: {
                type: 'category',
                data: ['a', 'b', 'c', 'd']
            },
            yAxis: {},
            series: [series]
        });
    }

    ([
        'start', 'middle', 'end'
    ] as const).forEach(function (step) {
        it(`areaStyle of step: '${step}' should not be skewed by nulls when connectNulls is true`, function () {
            setStepOption({
                type: 'line',
                step,
                connectNulls: true,
                areaStyle: {},
                data: [10, null, 30, 40]
            });

            const polygon = getPolyEl(chart, 'ec-polygon');
            const polyline = getPolyEl(chart, 'ec-polyline');

            // `ECPolygon` walks `points` forwards and `stackedOnPoints` backwards by
            // index, so they must have the very same length and the very same
            // progression on the base axis. Otherwise the area is skewed. See #20092
            expect(polygon.shape.stackedOnPoints.length).toEqual(polygon.shape.points.length);
            expect(getBaseCoords(polygon.shape.stackedOnPoints))
                .toEqual(getBaseCoords(polygon.shape.points));
            // The line and the area share the same top edge.
            expect(Array.prototype.slice.call(polygon.shape.points))
                .toEqual(Array.prototype.slice.call(polyline.shape.points));

            // Nulls are bridged, so no null is left in the generated step points.
            expect(getValueCoords(polygon.shape.points).filter(isNaN).length).toEqual(0);
        });

        it(`step: '${step}' should not bridge null gaps when connectNulls is false`, function () {
            setStepOption({
                type: 'line',
                step,
                areaStyle: {},
                data: [10, null, 30, 40]
            });

            const polygon = getPolyEl(chart, 'ec-polygon');

            expect(polygon.shape.stackedOnPoints.length).toEqual(polygon.shape.points.length);
            expect(getBaseCoords(polygon.shape.stackedOnPoints))
                .toEqual(getBaseCoords(polygon.shape.points));

            // The gap of the null value must be kept.
            expect(getValueCoords(polygon.shape.points).filter(isNaN).length).toBeGreaterThan(0);
        });
    });

    it('stacked step area should keep its base line aligned with the line', function () {
        chart.setOption({
            animation: false,
            xAxis: {
                type: 'category',
                data: ['a', 'b', 'c', 'd']
            },
            yAxis: {},
            series: [{
                type: 'line',
                step: 'start',
                stack: 'total',
                areaStyle: {},
                data: [10, 20, 30, 40]
            }, {
                type: 'line',
                step: 'start',
                stack: 'total',
                areaStyle: {},
                data: [5, 15, 25, 35]
            }]
        });

        const polygon = getPolyEl(chart, 'ec-polygon', 1);
        expect(getBaseCoords(polygon.shape.stackedOnPoints))
            .toEqual(getBaseCoords(polygon.shape.points));
        // The base line of the upper series is the step line of the lower one.
        const lowerPolyline = getPolyEl(chart, 'ec-polyline', 0);
        expect(Array.prototype.slice.call(polygon.shape.stackedOnPoints))
            .toEqual(Array.prototype.slice.call(lowerPolyline.shape.points));
    });

    it('should not produce dangling points when every value is null', function () {
        setStepOption({
            type: 'line',
            step: 'start',
            connectNulls: true,
            areaStyle: {},
            data: [null, null, null, null]
        });

        const polygon = getPolyEl(chart, 'ec-polygon');
        expect(polygon.shape.points.length).toEqual(0);
        expect(polygon.shape.stackedOnPoints.length).toEqual(0);
    });

    it('should keep the area aligned after a data update', function () {
        setStepOption({
            type: 'line',
            step: 'middle',
            connectNulls: true,
            areaStyle: {},
            data: [10, null, 30, 40]
        });
        chart.setOption({
            series: [{
                type: 'line',
                step: 'middle',
                connectNulls: true,
                areaStyle: {},
                data: [20, null, 35, 45]
            }]
        });

        const polygon = getPolyEl(chart, 'ec-polygon');
        expect(polygon.shape.stackedOnPoints.length).toEqual(polygon.shape.points.length);
        expect(getBaseCoords(polygon.shape.stackedOnPoints))
            .toEqual(getBaseCoords(polygon.shape.points));
    });
});

