 * state is always determined from `points`, since the base line of the area is
 * always defined (it falls back to the value origin) and therefore can't tell
 * where the gaps are.
 */
function turnPointsIntoStep(
    points: ArrayLike<number>,
    stackedOnPoints: ArrayLike<number>,
    coordSys: Cartesian2D | Polar,
    stepTurnAt: 'start' | 'end' | 'middle',
    connectNulls: boolean
): SteppedPoints {
    const baseAxis = coordSys.getBaseAxis();
    const baseIndex = baseAxis.dim === 'x' || baseAxis.dim === 'radius' ? 0 : 1;
    const hasStackedOn = !!stackedOnPoints;

    if (connectNulls) {
        // Bridge the null gaps by simply removing the null points. The same
        // indices have to be removed from the base line of the area.
        const filteredPoints: number[] = [];
        const filteredStackedOnPoints: number[] = hasStackedOn ? [] : null;
        for (let i = 0; i < points.length; i += 2) {
            if (!isNaN(points[i]) && !isNaN(points[i + 1])) {
                filteredPoints.push(points[i], points[i + 1]);
                if (hasStackedOn) {
                    filteredStackedOnPoints.push(stackedOnPoints[i], stackedOnPoints[i + 1]);
                }
            }
        }
        points = filteredPoints;
        stackedOnPoints = filteredStackedOnPoints;
    }

    const stepPt: number[] = [];
    const stepPt2: number[] = [];
    const pt: number[] = [];
    const nextPt: number[] = [];

    function toStepPoints(rawPoints: ArrayLike<number>): number[] {
        const stepPoints: number[] = [];
        let i = 0;
        for (i = 0; i < rawPoints.length - 2; i += 2) {
            nextPt[0] = rawPoints[i + 2];
            nextPt[1] = rawPoints[i + 3];
            pt[0] = rawPoints[i];
            pt[1] = rawPoints[i + 1];
            stepPoints.push(pt[0], pt[1]);

