interface SteppedPoints {
    points: NumericArray
    /**
     * `null` if no `stackedOnPoints` is given.
     */
    stackedOnPoints: NumericArray
}

/**
 * Generate the points of a step line.
 *
 * `stackedOnPoints` (the base line of the area of the series, see #20092) is
 * converted together with `points` on purpose: both arrays must stay index
 * aligned and share the very same progression on the base axis, otherwise
 * `ECPolygon` (which walks `points` forwards and `stackedOnPoints` backwards
 * by index) would build a skewed area.
 *
 * Null points are dropped **only** when `connectNulls` is enabled, so that the
 * gaps of a step line are not bridged when the user didn't ask for it. The null
 * state is always determined from `points`, since the base line of the area is
 * always defined (it falls back to the value origin) and therefore can't tell
 * where the gaps are.
 */
function turnPointsIntoStep(
    points: ArrayLike<number>,
    stackedOnPoints: ArrayLike<number>,
    coordSys: Cartesian2D | Polar,
    stepTurnAt: 'start' | 'end' | 'middle',
    connectNulls: boolean
): SteppedPoints {
    const baseAxis = coordSys.getBaseAxis();
    const baseIndex = baseAxis.dim === 'x' || baseAxis.dim === 'radius' ? 0 : 1;
    const valueIndex = 1 - baseIndex;
    const hasStackedOn = !!stackedOnPoints;
    const len = points.length;

    // Count the points that are kept. Null points are only dropped (which bridges
    // the gap) when `connectNulls` is enabled.
    let pointCount = len / 2;
    if (connectNulls) {
        pointCount = 0;
        for (let i = 0; i < len; i += 2) {
            if (!isNaN(points[i]) && !isNaN(points[i + 1])) {
                pointCount++;
            }
        }
    }

    // The amount of the generated points is known upfront, so they can be written
    // into exactly sized Float32Arrays. Compared with growing plain arrays (which
    // hold doubles) it roughly halves the memory that the shapes of a step line
    // keep alive, and it doesn't leave intermediate copies behind. See #20161
    const stepPointCount = pointCount > 0
        ? (stepTurnAt === 'middle' ? pointCount * 3 - 2 : pointCount * 2 - 1)
        : 0;
    const stepPoints = createFloat32Array(stepPointCount * 2);
    const stepStackedOnPoints = hasStackedOn ? createFloat32Array(stepPointCount * 2) : null;

    /**
     * Write the point at `srcOffset` and the turning point(s) between it and the
     * point at `nextSrcOffset` (`-1` if there is no next point) into `out`.
     * Returns the new write offset.
     */
    function writeStepPoints(
        src: ArrayLike<number>,
        out: NumericArray,
        outOffset: number,
        srcOffset: number,
        nextSrcOffset: number
    ): number {
        out[outOffset] = src[srcOffset];
        out[outOffset + 1] = src[srcOffset + 1];
        outOffset += 2;

        if (nextSrcOffset < 0) {
            // Last point.
            return outOffset;
        }

        const base = src[srcOffset + baseIndex];
        const value = src[srcOffset + valueIndex];
        const nextBase = src[nextSrcOffset + baseIndex];
        const nextValue = src[nextSrcOffset + valueIndex];

        switch (stepTurnAt) {
            case 'end':
                out[outOffset + baseIndex] = nextBase;
                out[outOffset + valueIndex] = value;
                outOffset += 2;
                break;
            case 'middle':
                const middle = (base + nextBase) / 2;
                out[outOffset + baseIndex] = middle;
                out[outOffset + valueIndex] = value;
                outOffset += 2;
                out[outOffset + baseIndex] = middle;
                out[outOffset + valueIndex] = nextValue;
                outOffset += 2;
                break;
            default:
                // default is start
                out[outOffset + baseIndex] = base;
                out[outOffset + valueIndex] = nextValue;
                outOffset += 2;
        }
        return outOffset;
    }

    let outOffset = 0;
    let prevSrcOffset = -1;
    for (let i = 0; i < len; i += 2) {
        if (connectNulls && (isNaN(points[i]) || isNaN(points[i + 1]))) {
            continue;
        }
        if (prevSrcOffset >= 0) {
            // Both arrays are written from the same offsets on purpose, so that
            // they can't get out of sync. See #20092
            const nextOutOffset = writeStepPoints(points, stepPoints, outOffset, prevSrcOffset, i);
            if (hasStackedOn) {
                writeStepPoints(stackedOnPoints, stepStackedOnPoints, outOffset, prevSrcOffset, i);
            }
            outOffset = nextOutOffset;
        }
        prevSrcOffset = i;
    }
    // Last point
    if (prevSrcOffset >= 0) {
        writeStepPoints(points, stepPoints, outOffset, prevSrcOffset, -1);
        if (hasStackedOn) {
            writeStepPoints(stackedOnPoints, stepStackedOnPoints, outOffset, prevSrcOffset, -1);
        }
    }

    return {
        points: stepPoints,
        stackedOnPoints: stepStackedOnPoints
    };
}

/**
 * Points that are actually used by `ECPolyline` / `ECPolygon`. They are the raw
 * layout points unless the series is a step line.
 */
function preparePolyPoints(
    points: NumericArray,
    stackedOnPoints: NumericArray,
    coordSys: Cartesian2D | Polar,
    step: LineSeriesOption['step'],
    connectNulls: boolean
): SteppedPoints {
    // TODO If stacked series is not step
    return step
        ? turnPointsIntoStep(points, stackedOnPoints, coordSys, step, connectNulls)
        : { points: points, stackedOnPoints: stackedOnPoints };
}

